export const source = "import WP_SALARY_PLAN:*; /*package */\n\nLocal date &Effdt;\nLocal string &IsWageProg;\n\nFunction SetSalPlanWPUI;\n   Local Row &row_SalPlan;\n   Local WP_SALARY_PLAN:WP_SAL_PLAN_UI &SAL_PLAN; /* class name */\n   \n   &row_SalPlan = GetRow();\n   &SAL_PLAN = create WP_SALARY_PLAN:WP_SAL_PLAN_UI();\n   &row_SalPlan = &SAL_PLAN.SetSalPlanWPUI(&row_SalPlan);\n   TransferPage(Page.SALARY_PLAN_TABLE2);\n   \nEnd-Function;\n\n\nEvaluate %Page\nWhen = Page.SALARY_PLAN_TABLE\n   SetSalPlanWPUI();\n   Break;\nWhen = Page.SALARY_GRADE_T3GBL\n   &Setid = SAL_PLAN_TBL.SETID;\n   &Sal_Admin_Plan = SAL_PLAN_TBL.SAL_ADMIN_PLAN;\n   &Effdt = SAL_GRADE_TBL.EFFDT;\n   \n   SQLExec(\"SELECT %DATEOUT(EFFDT) FROM PS_SAL_PLAN_WP A WHERE SETID = :1 AND SAL_ADMIN_PLAN = :2 AND EFFDT = (SELECT MAX(EFFDT) FROM PS_SAL_PLAN_TBL AA WHERE A.SETID = AA.SETID AND A.SAL_ADMIN_PLAN = AA.SAL_ADMIN_PLAN AND AA.EFFDT <= %DATEIN(:3))\", &Setid, &Sal_Admin_Plan, &Effdt, &Effdt);\n   \n   SAL_PLAN_WP_WRK.SETID = SAL_PLAN_TBL.SETID;\n   SAL_PLAN_WP_WRK.SAL_ADMIN_PLAN = SAL_PLAN_TBL.SAL_ADMIN_PLAN;\n   SAL_PLAN_WP_WRK.EFFDT = &Effdt;\n   \n   DoModalComponent(MenuName.SETUP_HRMS, BarName.PRODUCTS_5, ItemName.WAGE_PROGRESSION_GBL, Panel.SALARY_PLAN_TABLE2, \"C\", Record.SAL_PLAN_WP_WRK, SAL_PLAN_WP_WRK.SETID, SAL_PLAN_WP_WRK.SAL_ADMIN_PLAN, SAL_PLAN_WP_WRK.EFFDT);\n   \nEnd-Evaluate;\n";
export const program = Buffer.from(
  "",
  "hex"
);
